export async function rotateRefreshToken(sessionId: string, presentedToken: string) {
  const session = await sessions.lock(sessionId);
  if (session.refreshTokenHash !== hash(presentedToken)) throw new InvalidToken();
  const next = randomToken();
  await sessions.update(sessionId, {
    refreshTokenHash: hash(next),
    previousTokenHash: session.refreshTokenHash,
    previousTokenExpiresAt: Date.now() + 30_000,
  });
  return next;
}

export async function readProfile(userId: string) {
  const key = `profile:${userId}`;
  const hit = await redis.get(key);
  if (hit) return JSON.parse(hit);
  const profile = await db.profiles.find(userId);
  await redis.set(key, JSON.stringify(profile), { ex: 300 });
  return profile;
}

CREATE TABLE ledger_entries (
  id UUID PRIMARY KEY,
  account_id UUID NOT NULL,
  amount_cents BIGINT NOT NULL,
  reversal_of UUID REFERENCES ledger_entries(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- Ledger rows are immutable. Correct mistakes by inserting a reversing entry.
REVOKE UPDATE, DELETE ON ledger_entries FROM app_user;

export async function sendWeeklyDigest(user: User, stories: Story[]) {
  if (!user.preferences.weeklyDigest) return;
  const html = renderDigest(stories.slice(0, 10));
  await mailer.send({ to: user.email, subject: "Your weekly digest", html });
}

export function isInRollout(flag: string, actorId: string, percentage: number) {
  const bucket = stableHash(`${flag}:${actorId}`) % 10_000;
  return bucket < percentage * 100;
}
// Stable hashing keeps an actor in the same cohort across requests and deploys.

export function publishJob(name: string, payload: unknown) {
  return queue.publish(name, payload, {
    traceparent: activeSpan()?.traceparent,
    correlationId: requestContext.correlationId,
  });
}
// Workers restore both fields before starting their child span.

export async function createPayout(request: PayoutRequest) {
  return db.transaction(async (tx) => {
    const existing = await tx.payouts.findByIdempotencyKey(request.idempotencyKey);
    if (existing) return existing;
    return tx.payouts.insert({ ...request, state: "pending" });
  });
}

export async function stripeWebhook(rawBody: Buffer, signature: string) {
  const event = stripe.webhooks.constructEvent(rawBody, signature, env.STRIPE_SECRET);
  if (await events.wasProcessed(event.id)) return { duplicate: true };
  await queue.publish("stripe-events", event, { retry: { attempts: 8, backoff: "exponential" } });
  await events.markProcessed(event.id);
}

